<html>
<head>
<title>Cài đặt IPA</title>

<style type="text/css">
body { font-family: Arial, sans-serif; font-size: 12px; }
h1 { font-size: 16px; margin: 0px; }
h2 { font-size: 14px; margin: 0px; }
h3 { font-size: 12px; margin: 0px; }
p { margin-top: 0px; margin-bottom: 5px; }
a { color: #000000; text-decoration: none; }
a:hover { color: #FF0000; }
.tab { display: none; }
.tab.active { display: block; }
#tabs { margin-bottom: 20px; overflow: hidden; }
#tabs ul { list-style: none; margin: 0px; padding: 0px; }
#tabs li { display: inline; margin-right: 10px; }
</style>

<script type="text/javascript">
function showTab(name) {
  var i, element, tablinks
  element = document.getElementsByClassName("tab")
  for (i = 0; i < element.length; i++) {
    element[i].style.display = "none";
  }
  tablinks = document.getElementsByClassName("tablinks")
  for (i = 0; i < tablinks.length; i++) {
    tablinks[i].className = tablinks[i].className.replace(" active", "");
  }
  document.getElementById(name).style.display = "block";
  event.currentTarget.className += " active";
}
</script>

</head>
